def initialization() -> None:
    """Initializes work areas, counters, and opens files."""
    logger.info("Initializing")
    global WS_WORK_AREAS, WS_COUNTERS, WS_TOTALS, WS_CURRENT_DATETIME, WS_CURR_YEAR, WS_CURR_MONTH, WS_CURR_DAY, report_record
    WS_WORK_AREAS = ""
    WS_COUNTERS = 0
    WS_TOTALS = 0
    WS_CURRENT_DATETIME = "20240101"
    WS_CURR_YEAR = "2024"
    WS_CURR_MONTH = "01"
    WS_CURR_DAY = "01"
