    """Writes the details for the daily transaction report."""
    logger.info("Writing daily details")
    global WS_TRANS_COUNT, WS_TOTAL_DEPOSITS, WS_TOTAL_WITHDRAWALS, WS_TOTAL_TRANSFERS, report_record, WS_REPORT_DETAIL
    report_record.rpt_trans_count  = None  # TODO: was WS_TRANS_COUNT
    report_record.rpt_deposits  = None  # TODO: was WS_TOTAL_DEPOSITS
