def collect_metrics(ws_eof_flag: str) -> None:
    """Collects metrics."""
    logger.info("Collecting metrics")
    collect_transaction_metrics(ws_eof_flag)
    collect_customer_metrics(ws_eof_flag)
    collect_performance_metrics(ws_eof_flag)

def collect_transaction_metrics(ws_eof_flag: str) -> None:
    """Collects transaction metrics."""
    logger.info("Collecting transaction metrics")
    ws_total_trans_amount: Decimal = Decimal("0")
    ws_total_trans_count: int = 0
    ws_avg_trans_amount: Decimal = Decimal("0")
    while ws_eof_flag != 'Y':
        ws_trans_rec = read_transaction_file()
        if ws_trans_rec is None:
            ws_eof_flag = 'Y'
        else:
            ws_total_trans_count += 1
            ws_total_trans_amount += ws_trans_rec.trans_amount
    if ws_total_trans_count > 0:
        ws_avg_trans_amount = ws_total_trans_amount / ws_total_trans_count
    ws_eof_flag = 'N'

def collect_customer_metrics(ws_eof_flag: str, ws_period_start: str) -> None:
    """Collects customer metrics."""
    logger.info("Collecting customer metrics")
    ws_active_customers: int = 0
    ws_new_customers: int = 0
    ws_churned_customers: int = 0
    while ws_eof_flag != 'Y':
        ws_cust_rec = read_customer_file()
        if ws_cust_rec is None:
            ws_eof_flag = 'Y'
        else:
            if ws_cust_rec.cust_status == 'A':
                ws_active_customers += 1
            if ws_cust_rec.cust_open_date >= ws_period_start:
                ws_new_customers += 1
            if ws_cust_rec.cust_close_date >= ws_period_start:
                ws_churned_customers += 1
    ws_eof_flag = 'N'

def collect_performance_metrics(ws_eof_flag: str) -> None:
    """Collects performance metrics."""
    logger.info("Collecting performance metrics")
    ws_response_time_total: Decimal = Decimal("0")
    ws_response_count: int = 0
    while ws_eof_flag != 'Y':
        ws_perf_rec = read_perf_log_file()
        if ws_perf_rec is None:
            ws_eof_flag = 'Y'
        else:
            ws_response_time_total += ws_perf_rec.perf_response_time
            ws_response_count += 1
    if ws_response_count > 0:
        ws_avg_response_time = ws_response_time_total / ws_response_count
    ws_eof_flag = 'N'

def aggregate_data() -> None:
    """Aggregates data."""
    logger.info("Aggregating data")
    daily_aggregation()
    weekly_aggregation()
    monthly_aggregation()

def daily_aggregation(ws_process_date: str, ws_total_trans_count: int, ws_total_trans_amount: Decimal, ws_total_deposits: Decimal, ws_total_withdrawals: Decimal) -> None:
    """Performs daily aggregation."""
    logger.info("Performing daily aggregation")
    ws_daily_summary = DailySummary()
    daily_date = ws_process_date
    daily_trans_count = ws_total_trans_count
    daily_trans_amount = ws_total_trans_amount
    daily_deposits = ws_total_deposits
    daily_withdrawals = ws_total_withdrawals
    write_daily_summary_record(DailySummary(daily_date, daily_trans_count, daily_trans_amount, daily_deposits, daily_withdrawals))

def weekly_aggregation(ws_day_of_week: int, ws_week_number: int) -> None:
    """Performs weekly aggregation."""
    logger.info("Performing weekly aggregation")
    if ws_day_of_week == 7:
        ws_weekly_summary = WeeklySummary()
        weekly_week = ws_week_number
        sum_week_data()
        write_weekly_summary_record(ws_weekly_summary)

def sum_week_data() -> None:
    """Sums weekly data."""
    logger.info("Summing weekly data")
    weekly_trans_count: int = 0
    weekly_trans_amount: Decimal = Decimal("0")
    for _ in range(7):
        daily_summary = read_daily_summary()
        if daily_summary:
            weekly_trans_count += daily_summary.daily_trans_count
            weekly_trans_amount += daily_summary.daily_trans_amount

def monthly_aggregation(ws_end_of_month: str, ws_curr_month: str, ws_curr_year: str, ws_eof_flag: str) -> None:
    """Performs monthly aggregation."""
    logger.info("Performing monthly aggregation")
    if ws_end_of_month == 'Y':
        ws_monthly_summary = MonthlySummary()
        monthly_month = ws_curr_month
        monthly_year = ws_curr_year
        sum_month_data(ws_curr_month, ws_eof_flag)
        write_monthly_summary_record(ws_monthly_summary)

def sum_month_data(ws_curr_month: str, ws_eof_flag: str) -> None:
    """Sums monthly data."""
    logger.info("Summing monthly data")
    monthly_trans_count: int = 0
    monthly_trans_amount: Decimal = Decimal("0")
    monthly_new_accounts: int = 0
    monthly_closed_accounts: int = 0
    while ws_eof_flag != 'Y':
        ws_daily_sum_rec = read_daily_summary_file()
        if ws_daily_sum_rec is None:
            ws_eof_flag = 'Y'
        else:
            if ws_daily_sum_rec.daily_month == ws_curr_month:
                monthly_trans_count += ws_daily_sum_rec.daily_trans_count
                monthly_trans_amount += ws_daily_sum_rec.daily_trans_amount
    ws_eof_flag = 'N'

def calculate_kpi() -> None:
    """Calculates KPIs."""
    logger.info("Calculating KPIs")
    calc_financial_kpi()
    calc_operational_kpi()
    calc_customer_kpi()

def calc_financial_kpi(ws_total_assets: Decimal, ws_net_income: Decimal, ws_total_equity: Decimal, ws_interest_expense: Decimal, ws_interest_income: Decimal, ws_earning_assets: Decimal) -> None:
    """Calculates financial KPIs."""
    logger.info("Calculating financial KPIs")
    ws_roa: Decimal = Decimal("0")
    ws_roe: Decimal = Decimal("0")
    ws_nim: Decimal = Decimal("0")
    if ws_total_assets > 0:
        ws_roa = (ws_net_income / ws_total_assets) * 100
    if ws_total_equity > 0:
        ws_roe = (ws_net_income / ws_total_equity) * 100
    if ws_interest_expense > 0:
        ws_nim = ((ws_interest_income - ws_interest_expense) / ws_earning_assets) * 100

def calc_operational_kpi(ws_total_trans_count: int, ws_error_count: int, ws_within_sla_count: int, ws_total_cases: int, ws_fcr_count: int, ws_total_calls: int) -> None:
    """Calculates operational KPIs."""
    logger.info("Calculating operational KPIs")
    ws_error_rate: Decimal = Decimal("0")
    ws_sla_compliance: Decimal = Decimal("0")
    ws_first_call_resolution: Decimal = Decimal("0")
    if ws_total_trans_count > 0:
        ws_error_rate = (ws_error_count / ws_total_trans_count) * 100
    ws_sla_compliance = (ws_within_sla_count / ws_total_cases) * 100
    ws_first_call_resolution = (ws_fcr_count / ws_total_calls) * 100

def calc_customer_kpi(ws_active_customers: int, ws_churned_customers: int, ws_marketing_spend: Decimal, ws_new_customers: int, ws_avg_revenue_per_customer: Decimal, ws_avg_customer_tenure: Decimal) -> None:
    """Calculates customer KPIs."""
    logger.info("Calculating customer KPIs")
    ws_churn_rate: Decimal = Decimal("0")
    ws_acquisition_cost: Decimal = Decimal("0")
    ws_lifetime_value: Decimal = Decimal("0")
    if ws_active_customers > 0:
        ws_churn_rate = (ws_churned_customers / ws_active_customers) * 100
    ws_acquisition_cost = ws_marketing_spend / ws_new_customers
    ws_lifetime_value = ws_avg_revenue_per_customer * ws_avg_customer_tenure

