def validate_card() -> None:
    """Validates card."""
    logger.info("Validating card")
    WS_CARD_VALID = 'N';
    check_luhn();
    if WS_LUHN_VALID == 'Y':
        check_expiry();
        if WS_NOT_EXPIRED == 'Y':
            check_cvv();
            if WS_CVV_VALID == 'Y':
                WS_CARD_VALID = 'Y';

def check_luhn() -> None:
    """Checks LUHN."""
    logger.info("Checking LUHN")
    WS_LUHN_SUM = 0;
    WS_LUHN_IDX = 16
    while not (WS_LUHN_IDX < 1):
        WS_LUHN_DIGIT = int(str(WS_AUTH_CARD_NUMBER)[WS_LUHN_idx_1:WS_LUHN_IDX])
        if (17 - WS_LUHN_IDX) % 2 == 0:
            WS_LUHN_DIGIT *= 2
            if WS_LUHN_DIGIT > 9:
                WS_LUHN_DIGIT -= 9
        WS_LUHN_SUM += WS_LUHN_DIGIT;
        WS_LUHN_IDX -= 1
    if WS_LUHN_SUM % 10 == 0:
        WS_LUHN_VALID = 'Y';
    else:
        WS_LUHN_VALID = 'N';

def check_expiry() -> None:
    """Checks expiry."""
    logger.info("Checking expiry")
    if WS_AUTH_EXPIRY_DATE >= WS_PROCESS_DATE:
        WS_NOT_EXPIRED = 'Y';
    else:
        WS_NOT_EXPIRED = 'N';

def check_cvv() -> None:
    """Checks CVV."""
